export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface QuoteStep {
  op: "quote";
  items: { type: string; material?: string; enchantment?: number; cursed?: boolean }[];
}

export type Step = QuoteStep;

export interface ScenarioResults {
  results: ({ premium: number } | { payout: number; remainingCap: number })[];
}

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return undefined as unknown as ScenarioResults;
};

