import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Edge case: empty policy ---
  it("quotes an empty item list at 5 G (processing fee only)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums for main items (newcomer: +10% first insurance, +5 fee) ---
  it("quotes a plain sword (base 100 G) at 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes a plain amulet (base 60 G) at 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it.todo("quotes a plain staff (base 80 G) at 93 G");
  it.todo("quotes a plain potion (base 40 G) at 49 G");

  // --- Components and the block of 3 alike ---
  it.todo("quotes 1 rune at base premium 25 G");
  it.todo("quotes 2 runes at base premium 50 G");
  it.todo("quotes 3 runes at base premium 60 G (block applies)");
  it.todo("quotes 4 runes at base premium 100 G (no block — block requires exactly 3)");
  it.todo("quotes 7 runes at base premium 175 G");
  it.todo("quotes 2 runes + 1 moonstone at base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones at base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed sword's base premium (100 G → 150 G)");
  it.todo("adds a 30 % surcharge for a sword with exactly enchantment 5 (100 G → 130 G)");
  it.todo("adds no high-enchantment surcharge for a sword with enchantment 4");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (100 G → 180 G)");

  // --- Modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item: cursed sword + plain amulet → 210 G before further modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("grants the 20 % loyalty discount to a customer with exactly 2 years with MHPCO");
  it.todo("grants no loyalty discount to a customer with 1 year with MHPCO");
  it.todo("adds the 10 % first insurance surcharge on the policy base premium");
  it.todo("grants a 15 % follow-up discount on the second quote of a scenario");
  it.todo("grants the 15 % follow-up discount on every quote after the first");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed sword (steel, enchantment 3) at 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) at 160 G");

  // --- Claims: standard reimbursement ---
  it.todo("pays 400 G for a regular sword (steel, enchantment 3) damaged by 500 G (deductible 100 G)");
  it.todo("pays 100 G for a rune (insurance value 250 G) damaged by 200 G");

  // --- Claims: special clauses ---
  it.todo("pays 400 G for a dragon-material sword with exactly enchantment 8 damaged by 1000 G (50 % clause, then deductible)");
  it.todo("pays 400 G for a dragon-material sword with enchantment 9 damaged by 1000 G (50 % rule wins over dragon material)");
  it.todo("pays 700 G for a dragon-material sword with enchantment 5 damaged by 800 G (full reimbursement, then deductible)");
  it.todo("pays 400 G for a steel sword with enchantment 9 damaged by 1000 G (50 % clause, then deductible)");

  // --- Claims: deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G → payout 600 G");

  // --- Claims: insurance sum and cap ---
  it.todo("reports the remaining cap of a policy after a claim");
  it.todo("caps a policy covering a sword and an amulet at 3200 G (insurance sum 1600 G)");
  it.todo("caps a policy covering a cursed sword at 2000 G (premium modifiers do not raise the cap)");
  it.todo("caps a policy covering a sword and 3 runes at 3500 G (insurance sum 1750 G — the block discount affects the premium only)");
  it.todo("exhausts the cap across successive claims: 1500 G → payout 1400 G / cap 600 G, then 1500 G → payout 600 G / cap 0 G");

  // --- Multiple items of the same type ---
  it.todo("insures two swords at an insurance sum of 2000 G (cap 4000 G)");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers");

  // --- Errors ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick)");
  it.todo("rejects a claim referencing a damaged item that is not part of the policy");
  it.todo("rejects a claim containing a damage entry with a negative amount");
});

