export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface QuoteStep {
  op: "quote";
  items: {
    type: KnownItemType;
    material?: string;
    enchantment?: number;
    cursed?: boolean;
  }[];
}

export type Step = QuoteStep;

export interface ScenarioResults {
  results: ({ premium: number } | { payout: number; remainingCap: number })[];
}

const PROCESSING_FEE = 5;
const BASE_PREMIUM_BY_TYPE = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
} as const satisfies Record<string, number>;

export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
const FIRST_INSURANCE_SURCHARGE = 0.1;

// Percentage arithmetic leaves values like 71.00000000000001, which would
// otherwise round up to 72. Settle the float noise before rounding.
const FLOAT_NOISE_DIGITS = 6;
const withoutFloatNoise = (amount: number): number =>
  Number(amount.toFixed(FLOAT_NOISE_DIGITS));

const roundUpInFavourOfMHPCO = (amount: number): number =>
  Math.ceil(withoutFloatNoise(amount));

type Item = QuoteStep["items"][number];

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const increasedBy = (amount: number, rate: number): number =>
  amount * (1 + rate);

const policyBasePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const quotePremium = (step: QuoteStep): number =>
  roundUpInFavourOfMHPCO(
    increasedBy(policyBasePremiumOf(step.items), FIRST_INSURANCE_SURCHARGE) +
      PROCESSING_FEE,
  );

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

