  it.todo("pays 400 G for a steel sword with enchantment 9 damaged by 1000 G (50 % clause, then deductible)");

  // --- Claims: deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G → payout 600 G");

  // --- Claims: insurance sum and cap ---
  it.todo("reports the remaining cap of a policy after a claim");
  it.todo("caps a policy covering a sword and an amulet at 3200 G (insurance sum 1600 G)");
