export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface QuoteStep {
  op: "quote";
  items: {
    type: KnownItemType;
    material?: string;
    enchantment?: number;
    cursed?: boolean;
  }[];
}

export type Step = QuoteStep;

export interface ScenarioResults {
  results: ({ premium: number } | { payout: number; remainingCap: number })[];
}

const PROCESSING_FEE = 5;
const BASE_PREMIUM_BY_TYPE = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
const FIRST_INSURANCE_SURCHARGE = 0.1;

// Percentage arithmetic leaves values like 71.00000000000001, which would
// otherwise round up to 72. Settle the float noise before rounding.
const FLOAT_NOISE_DIGITS = 6;
const withoutFloatNoise = (amount: number): number =>
  Number(amount.toFixed(FLOAT_NOISE_DIGITS));

const roundUpInFavourOfMHPCO = (amount: number): number =>
  Math.ceil(withoutFloatNoise(amount));

type Item = QuoteStep["items"][number];

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const increasedBy = (amount: number, rate: number): number =>
  amount * (1 + rate);

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<KnownItemType, Item[]>();
  for (const item of items) {
    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
  }
  return [...groups.values()];
};

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

// Exactly three alike components form a block at a reduced premium; any
// other count is priced per item.
//
// Deliberate simplification: "component" is not yet enforced, so three alike
// swords would also get the block. No test covers it and the spec gives no
// example — revisit when one does.
const groupBasePremiumOf = (group: Item[]): number =>
  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);

const policyBasePremiumOf = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);

const CURSE_SURCHARGE = 0.5;

// Item-specific modifiers are charged as a percentage of the affected item's
// OWN base premium, unlike policy-wide modifiers which scale the policy base.
const surchargeOn = (item: Item, rate: number): number =>
  basePremiumOf(item) * rate;

const surchargesOn = (item: Item): number =>
  item.cursed ? surchargeOn(item, CURSE_SURCHARGE) : 0;

const itemSurchargesOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + surchargesOn(item), 0);

const quotePremium = (step: QuoteStep): number => {
  const policyBase = policyBasePremiumOf(step.items);
  const policyBaseWithFirstInsurance = increasedBy(
    policyBase,
    FIRST_INSURANCE_SURCHARGE,
  );
  return roundUpInFavourOfMHPCO(
    policyBaseWithFirstInsurance + itemSurchargesOf(step.items) + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

