  ITEM_SURCHARGES.filter(({ applies }) => applies(item)).reduce(
    (rate, surcharge) => rate + surcharge.rate,
    0,
  );

const surchargeOn = (item: Item): number =>
  shareOfOwnBasePremium(item, surchargeRateOn(item));

const itemSurchargesOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + surchargeOn(item), 0);

// Policy-wide modifiers scale the whole policy base premium, unlike item
// modifiers which are charged against the affected item's own base premium.
// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
// its base — not 110 % × 80 %.
const POLICY_WIDE_MODIFIER_RATES = [FIRST_INSURANCE_SURCHARGE];

const withPolicyWideModifiers = (policyBase: number): number => {
  const totalRate = POLICY_WIDE_MODIFIER_RATES.reduce(
    (total, rate) => total + rate,
    0,
  );
  return policyBase * (1 + totalRate);
};

const quotePremium = ({ items }: QuoteStep): number =>
  roundUpInFavourOfMHPCO(
    withPolicyWideModifiers(policyBasePremiumOf(items)) +
      itemSurchargesOf(items) +
      PROCESSING_FEE,
  );

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

