): StepRun => {
  // A claim always names a policy an earlier quote step created. Nothing
  // validates that yet — the test rejecting unknown references will force the
  // question of what to do when it is absent.
  const policy = state.policies.get(policyIndex) ?? {
    items: [],
    remainingCap: 0,
  };
  // Gross: what the damages reimburse before the policy's own limit is
  // consulted. coverage.ts computes this without reference to remainingCap,
  // so on a policy with less cap left than the damages come to, this exceeds
  // what the policy can actually pay. The spec's cap-exhaustion example is
  // still it.todo(); until it lands, gross and settled coincide on every
  // covered case, and the name marks which of the two this is.
  const grossPayout = payoutForDamages(policy.items, incident.damages);
  const remainingCap = policy.remainingCap - grossPayout;

  return {
    outcome: { payout: grossPayout, remainingCap },
    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
  };
};

