// How a scenario unfolds. This module knows the order events happen in and
// what each step leaves behind for the next one; it delegates what a policy
// costs to pricing.ts and what it pays out to coverage.ts.

import { premiumFor, type Customer, type Item } from "./pricing.js";
import { capFor, payoutForDamages, type Damage } from "./coverage.js";

export type { Customer, KnownItemType } from "./pricing.js";
export type { Damage } from "./coverage.js";

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface ScenarioResults {
  results: ({ premium: number } | { payout: number; remainingCap: number })[];
}

// What earlier steps have established by the time a later step is priced.
// Steps are not independent: a quote is a follow-up contract when the customer
// already took a quote earlier in the same scenario. Folding this forward —
// rather than re-deriving it from the step prefix — is what lets a step read
// the state its predecessors left behind.
interface Policy {
  // The insured items, kept because a claim is settled against them: what a
  // damage reimburses depends on the item's own material and enchantment, not
  // on the damage entry alone.
  items: Item[];
  remainingCap: number;
}

interface ScenarioState {
  hasQuoted: boolean;
  // Keyed by the step index of the quote that created the policy, which is
  // how a later claim step refers to it.
  policies: Map<number, Policy>;
}

const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };

type StepOutcome = ScenarioResults["results"][number];

interface StepRun {
  outcome: StepOutcome;
  state: ScenarioState;
}

// Every policy a step establishes is recorded the same way, so both handlers
// go through here rather than each rebuilding the map.
const withPolicy = (
  state: ScenarioState,
  index: number,
  policy: Policy,
): ScenarioState => ({
  ...state,
  policies: new Map(state.policies).set(index, policy),
});

const runQuote = (
  { items }: QuoteStep,
  customer: Customer,
  state: ScenarioState,
  index: number,
): StepRun => ({
  outcome: {
    premium: premiumFor(items, {
      customer,
      isFollowUpContract: state.hasQuoted,
    }),
  },
  state: withPolicy({ ...state, hasQuoted: true }, index, {
    items,
    remainingCap: capFor(items),
  }),
});

const runClaim = (
  { policy: policyIndex, incident }: ClaimStep,
  state: ScenarioState,
): StepRun => {
  // A claim always names a policy an earlier quote step created. Nothing
  // validates that yet — the test rejecting unknown references will force the
  // question of what to do when it is absent.
  const policy = state.policies.get(policyIndex) ?? {
    items: [],
    remainingCap: 0,
  };
  // Gross: what the damages reimburse before the policy's own limit is
  // consulted. coverage.ts computes this without reference to remainingCap,
  // so on a policy with less cap left than the damages come to, this exceeds
  // what the policy can actually pay. The spec's cap-exhaustion example is
  // still it.todo(); until it lands, gross and settled coincide on every
  // covered case, and the name marks which of the two this is.
  const grossPayout = payoutForDamages(policy.items, incident.damages);
  const remainingCap = policy.remainingCap - grossPayout;

  return {
    outcome: { payout: grossPayout, remainingCap },
    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
  };
};

// Dispatches a step to its handler. Written as an exhaustive switch on `op`
// so that adding a step kind to the Step union turns "I forgot to handle it"
// into a compile error rather than a wrong number.
const runStep = (
  step: Step,
  customer: Customer,
  state: ScenarioState,
  index: number,
): StepRun => {
  switch (step.op) {
    case "quote":
      return runQuote(step, customer, state, index);
    case "claim":
      return runClaim(step, state);
  }
};

export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
  const { results } = steps.reduce<{
    results: StepOutcome[];
    state: ScenarioState;
  }>(
    ({ results, state }, step, index) => {
      const stepRun = runStep(step, customer, state, index);
      return { results: [...results, stepRun.outcome], state: stepRun.state };
    },
    { results: [], state: INITIAL_STATE },
  );

  return { results };
};

