  applies: (item: Item) => boolean;
  share: number;
}[] = [
  { applies: qualifiesForHalfReimbursement, share: HALF_REIMBURSEMENT_SHARE },
  { applies: () => true, share: FULL_REIMBURSEMENT_SHARE },
